using FixFinder.Core.LocalFixes;
using FixFinder.Core.Logic;

namespace FixFinder.Tests;

/// <summary>
/// A quickselect in each language that asks the part above the pivot for place k as it is, with the change that takes away
/// how many items come up to the pivot; the same selections taking them away, and programs near the mistake but not it,
/// which are left alone. Each row is what the check gave for the
/// program when these were written.
/// </summary>
public class PlaceNotTakenAwayTests : IDisposable
{
    private readonly TempFolder _temp = new();

    public void Dispose()
    {
        _temp.Dispose();
        GC.SuppressFinalize(this);
    }

    private SourceFile Program(string fileName, string code)
    {
        var path = Path.Combine(_temp.Path, fileName);
        File.WriteAllText(path, code);
        return SourceFile.Read(path)!;
    }

    /// <summary>The file, the program, the check, the line it is said of, the line the change starts on, how many it takes away, and the lines it writes, one a line.</summary>
    public static TheoryData<string, string, string, int, int, int, string> Mistakes => new()
    {
        { "kth.c", "#include <stdio.h>\n\nint kth(const int *items, int count, int k) {\n    int pivot = items[0], below[16], above[16], num_below = 0, num_above = 0;\n    for (int i = 0; i < count; i++) {\n        if (items[i] < pivot) below[num_below++] = items[i];\n        else if (items[i] > pivot) above[num_above++] = items[i];\n    }\n    int less_or_equal = count - num_above;\n    if (k < num_below) return kth(below, num_below, k);\n    if (k >= less_or_equal) return kth(above, num_above, k);\n    return pivot;\n}\n\nint main(void) {\n    int items[] = {4, 9, 2, 7, 4, 1, 8};\n    for (int k = 0; k < 7; k++) printf(k > 0 ? \" %d\" : \"%d\", kth(items, 7, k));\n    printf(\"\\n\");\n    return 0;\n}\n", "logic-c-place-not-taken-away", 11, 11, 1, "    if (k >= less_or_equal) return kth(above, num_above, k - less_or_equal);" },
        { "kth.cpp", "#include <iostream>\n#include <vector>\n\nint kth(const std::vector<int>& items, int k) {\n    int pivot = items[0];\n    std::vector<int> below, above;\n    for (int x : items) {\n        if (x < pivot) below.push_back(x);\n        else if (x > pivot) above.push_back(x);\n    }\n    int lessOrEqual = static_cast<int>(items.size() - above.size());\n    if (k < static_cast<int>(below.size())) {\n        return kth(below, k);\n    }\n    if (k >= lessOrEqual) {\n        return kth(above, k);\n    }\n    return pivot;\n}\n\nint main() {\n    std::vector<int> items = {4, 9, 2, 7, 4, 1, 8};\n    for (int k = 0; k < static_cast<int>(items.size()); k++) std::cout << (k > 0 ? \" \" : \"\") << kth(items, k);\n    std::cout << std::endl;\n    return 0;\n}\n", "logic-cpp-place-not-taken-away", 16, 16, 1, "        return kth(above, k - lessOrEqual);" },
        { "kth.dart", "int kth(List<int> items, int k) {\n  final pivot = items[0];\n  final below = items.where((x) => x < pivot).toList();\n  final above = items.where((x) => x > pivot).toList();\n  final lessOrEqual = items.length - above.length;\n  if (k < below.length) {\n    return kth(below, k);\n  }\n  if (k >= lessOrEqual) {\n    return kth(above, k);\n  }\n  return pivot;\n}\n\nvoid main() {\n  final items = [4, 9, 2, 7, 4, 1, 8];\n  print(List.generate(items.length, (k) => kth(items, k)).join(' '));\n}\n", "logic-dart-place-not-taken-away", 10, 10, 1, "    return kth(above, k - lessOrEqual);" },
        { "kth.f90", "module select_module\n  implicit none\ncontains\n  recursive function kth(items, k) result(found)\n    integer, intent(in) :: items(:), k\n    integer :: found, pivot, less_or_equal\n    pivot = items(1)\n    less_or_equal = size(items) - count(items > pivot)\n    if (k <= count(items < pivot)) then\n      found = kth(pack(items, items < pivot), k)\n    else if (k > less_or_equal) then\n      found = kth(pack(items, items > pivot), k)\n    else\n      found = pivot\n    end if\n  end function kth\nend module select_module\n\nprogram kth_program\n  use select_module\n  implicit none\n  integer :: items(7) = [4, 9, 2, 7, 4, 1, 8], k, found(7)\n  do k = 1, 7\n    found(k) = kth(items, k)\n  end do\n  print '(*(I0, :, 1X))', found\nend program kth_program\n", "logic-fortran-place-not-taken-away", 12, 12, 1, "      found = kth(pack(items, items > pivot), k - less_or_equal)" },
        { "kth.go", "package main\n\nimport (\n\t\"fmt\"\n\t\"strings\"\n)\n\nfunc kth(items []int, k int) int {\n\tpivot := items[0]\n\tvar below, above []int\n\tfor _, x := range items {\n\t\tif x < pivot {\n\t\t\tbelow = append(below, x)\n\t\t} else if x > pivot {\n\t\t\tabove = append(above, x)\n\t\t}\n\t}\n\tlessOrEqual := len(items) - len(above)\n\tif k < len(below) {\n\t\treturn kth(below, k)\n\t}\n\tif k >= lessOrEqual {\n\t\treturn kth(above, k)\n\t}\n\treturn pivot\n}\n\nfunc main() {\n\titems := []int{4, 9, 2, 7, 4, 1, 8}\n\tvar words []string\n\tfor k := range items {\n\t\twords = append(words, fmt.Sprint(kth(items, k)))\n\t}\n\tfmt.Println(strings.Join(words, \" \"))\n}\n", "logic-go-place-not-taken-away", 23, 23, 1, "\t\treturn kth(above, k - lessOrEqual)" },
        { "Kth.java", "import java.util.ArrayList;\nimport java.util.List;\n\npublic class Kth {\n    static int kth(List<Integer> arr, int k) {\n        int pivot = arr.get(0);\n        List<Integer> below = new ArrayList<>();\n        List<Integer> above = new ArrayList<>();\n        for (int x : arr) {\n            if (x < pivot) {\n                below.add(x);\n            } else if (x > pivot) {\n                above.add(x);\n            }\n        }\n        int numLess = below.size();\n        int numLessOrEqual = arr.size() - above.size();\n        if (k < numLess) {\n            return kth(below, k);\n        } else if (k >= numLessOrEqual) {\n            return kth(above, k);\n        } else {\n            return pivot;\n        }\n    }\n\n    public static void main(String[] args) {\n        List<Integer> items = List.of(4, 9, 2, 7, 4, 1, 8);\n        StringBuilder line = new StringBuilder();\n        for (int k = 0; k < items.size(); k++) line.append(k > 0 ? \" \" : \"\").append(kth(items, k));\n        System.out.println(line);\n    }\n}\n", "logic-java-place-not-taken-away", 21, 21, 1, "            return kth(above, k - numLessOrEqual);" },
        { "kth.js", "function kth(items, k) {\n  const pivot = items[0];\n  const below = items.filter((x) => x < pivot);\n  const above = items.filter((x) => x > pivot);\n  const lessOrEqual = items.length - above.length;\n  if (k < below.length) return kth(below, k);\n  if (k >= lessOrEqual) return kth(above, k);\n  return pivot;\n}\n\nconst items = [4, 9, 2, 7, 4, 1, 8];\nconsole.log(items.map((_, k) => kth(items, k)).join(\" \"));\n", "logic-js-place-not-taken-away", 7, 7, 1, "  if (k >= lessOrEqual) return kth(above, k - lessOrEqual);" },
        { "kth.lua", "local function kth(items, k)\n  local pivot = items[1]\n  local below, above = {}, {}\n  for _, x in ipairs(items) do\n    if x < pivot then\n      below[#below + 1] = x\n    elseif x > pivot then\n      above[#above + 1] = x\n    end\n  end\n  local less_or_equal = #items - #above\n  if k <= #below then\n    return kth(below, k)\n  elseif k > less_or_equal then\n    return kth(above, k)\n  end\n  return pivot\nend\n\nlocal items = { 4, 9, 2, 7, 4, 1, 8 }\nlocal words = {}\nfor k = 1, #items do\n  words[k] = kth(items, k)\nend\nprint(table.concat(words, \" \"))\n", "logic-lua-place-not-taken-away", 15, 15, 1, "    return kth(above, k - less_or_equal)" },
        { "kth.php", "<?php\nfunction kth(array $items, int $k): int\n{\n    $pivot = $items[0];\n    $below = array_values(array_filter($items, fn($x) => $x < $pivot));\n    $above = array_values(array_filter($items, fn($x) => $x > $pivot));\n    $lessOrEqual = count($items) - count($above);\n    if ($k < count($below)) {\n        return kth($below, $k);\n    }\n    if ($k >= $lessOrEqual) {\n        return kth($above, $k);\n    }\n    return $pivot;\n}\n\n$items = [4, 9, 2, 7, 4, 1, 8];\necho implode(\" \", array_map(fn($k) => kth($items, $k), range(0, count($items) - 1))), \"\\n\";\n", "logic-php-place-not-taken-away", 12, 12, 1, "        return kth($above, $k - $lessOrEqual);" },
        { "kth.pl", "use strict;\nuse warnings;\n\nsub kth {\n    my ($items, $k) = @_;\n    my $pivot = $items->[0];\n    my @below = grep { $_ < $pivot } @$items;\n    my @above = grep { $_ > $pivot } @$items;\n    my $less_or_equal = @$items - @above;\n    if ($k < @below) {\n        return kth(\\@below, $k);\n    }\n    if ($k >= $less_or_equal) {\n        return kth(\\@above, $k);\n    }\n    return $pivot;\n}\n\nmy @items = (4, 9, 2, 7, 4, 1, 8);\nprint join(\" \", map { kth(\\@items, $_) } 0 .. $#items), \"\\n\";\n", "logic-perl-place-not-taken-away", 14, 14, 1, "        return kth(\\@above, $k - $less_or_equal);" },
        { "kth.ps1", "function Get-Kth($items, [int]$k) {\n    $pivot = $items[0]\n    $below = @($items | Where-Object { $_ -lt $pivot })\n    $above = @($items | Where-Object { $_ -gt $pivot })\n    $lessOrEqual = $items.Count - $above.Count\n    if ($k -lt $below.Count) {\n        return Get-Kth $below $k\n    }\n    if ($k -ge $lessOrEqual) {\n        return Get-Kth $above ($k)\n    }\n    return $pivot\n}\n\n$items = @(4, 9, 2, 7, 4, 1, 8)\n(0..($items.Count - 1) | ForEach-Object { Get-Kth $items $_ }) -join \" \"\n", "logic-powershell-place-not-taken-away", 10, 10, 1, "        return Get-Kth $above ($k - $lessOrEqual)" },
        { "kth.py", "def kth(arr, k):\n    pivot = arr[0]\n    below = [x for x in arr if x < pivot]\n    above = [x for x in arr if x > pivot]\n\n    num_less = len(below)\n    num_lessoreq = len(arr) - len(above)\n\n    if k < num_less:\n        return kth(below, k)\n    elif k >= num_lessoreq:\n        return kth(above, k)\n    else:\n        return pivot\n\n\nitems = [4, 9, 2, 7, 4, 1, 8]\nprint(*(kth(items, k) for k in range(len(items))))\n", "logic-python-place-not-taken-away", 12, 12, 1, "        return kth(above, k - num_lessoreq)" },
        { "kth.rb", "def kth(items, k)\n  pivot = items[0]\n  below = items.select { |x| x < pivot }\n  above = items.select { |x| x > pivot }\n  less_or_equal = items.length - above.length\n  if k < below.length\n    kth(below, k)\n  elsif k >= less_or_equal\n    kth(above, k)\n  else\n    pivot\n  end\nend\n\nitems = [4, 9, 2, 7, 4, 1, 8]\nputs (0...items.length).map { |k| kth(items, k) }.join(\" \")\n", "logic-ruby-place-not-taken-away", 9, 9, 1, "    kth(above, k - less_or_equal)" },
        { "kth.rs", "fn kth(items: &[i32], k: usize) -> i32 {\n    let pivot = items[0];\n    let below: Vec<i32> = items.iter().copied().filter(|&x| x < pivot).collect();\n    let above: Vec<i32> = items.iter().copied().filter(|&x| x > pivot).collect();\n    let less_or_equal = items.len() - above.len();\n    if k < below.len() {\n        return kth(&below, k);\n    }\n    if k >= less_or_equal {\n        return kth(&above, k);\n    }\n    pivot\n}\n\nfn main() {\n    let items = [4, 9, 2, 7, 4, 1, 8];\n    let words: Vec<String> = (0..items.len()).map(|k| kth(&items, k).to_string()).collect();\n    println!(\"{}\", words.join(\" \"));\n}\n", "logic-rust-place-not-taken-away", 10, 10, 1, "        return kth(&above, k - less_or_equal);" },
        { "Kth.scala", "object Kth {\n  def kth(items: List[Int], k: Int): Int = {\n    val pivot = items.head\n    val below = items.filter(_ < pivot)\n    val above = items.filter(_ > pivot)\n    val lessOrEqual = items.length - above.length\n    if (k < below.length) {\n      kth(below, k)\n    } else if (k >= lessOrEqual) {\n      kth(above, k)\n    } else {\n      pivot\n    }\n  }\n\n  def main(args: Array[String]): Unit = {\n    val items = List(4, 9, 2, 7, 4, 1, 8)\n    println(items.indices.map(kth(items, _)).mkString(\" \"))\n  }\n}\n", "logic-scala-place-not-taken-away", 10, 10, 1, "      kth(above, k - lessOrEqual)" },
        { "kth.ts", "function kth(items: number[], k: number): number {\n  const pivot = items[0];\n  const below = items.filter((x) => x < pivot);\n  const above = items.filter((x) => x > pivot);\n  const lessOrEqual = items.length - above.length;\n  if (k < below.length) {\n    return kth(below, k);\n  }\n  if (k >= lessOrEqual) {\n    return kth(above, k);\n  }\n  return pivot;\n}\n\nconst items: number[] = [4, 9, 2, 7, 4, 1, 8];\nconsole.log(items.map((_, k) => kth(items, k)).join(\" \"));\n", "logic-js-place-not-taken-away", 10, 10, 1, "    return kth(above, k - lessOrEqual);" },
