    [Theory]
    [MemberData(nameof(Mistakes))]
    public void APlaceAskedOfThePartAboveAsItIsIsFound(string fileName, string code, string check, int line, int changeAt, int removed, string added)
    {
        var found = Assert.Single(LogicPatterns.All.Where(pattern => pattern.Id == check).SelectMany(pattern => pattern.Find(Program(fileName, code))));

        Assert.Equal(line, found.Line);
        Assert.Equal(changeAt, found.Fix!.StartLine);
        Assert.Equal(removed, found.Fix.RemoveCount);
        Assert.Equal(added.Split('\n'), found.Fix.NewLines);
    }

    /// <summary>
    /// The selections taking the count away; a quickselect in place, whose k is a place in the whole array and so is kept;
    /// the k-th largest, which keeps k going into the part above because that part comes first; and a binary search that
    /// keeps its target in each half.
    /// </summary>
    [Theory]
    [InlineData("kth.c", "#include <stdio.h>\n\nint kth(const int *items, int count, int k) {\n    int pivot = items[0], below[16], above[16], num_below = 0, num_above = 0;\n    for (int i = 0; i < count; i++) {\n        if (items[i] < pivot) below[num_below++] = items[i];\n        else if (items[i] > pivot) above[num_above++] = items[i];\n    }\n    int less_or_equal = count - num_above;\n    if (k < num_below) return kth(below, num_below, k);\n    if (k >= less_or_equal) return kth(above, num_above, k - less_or_equal);\n    return pivot;\n}\n\nint main(void) {\n    int items[] = {4, 9, 2, 7, 4, 1, 8};\n    for (int k = 0; k < 7; k++) printf(k > 0 ? \" %d\" : \"%d\", kth(items, 7, k));\n    printf(\"\\n\");\n    return 0;\n}\n")]
    [InlineData("kth.cpp", "#include <iostream>\n#include <vector>\n\nint kth(const std::vector<int>& items, int k) {\n    int pivot = items[0];\n    std::vector<int> below, above;\n    for (int x : items) {\n        if (x < pivot) below.push_back(x);\n        else if (x > pivot) above.push_back(x);\n    }\n    int lessOrEqual = static_cast<int>(items.size() - above.size());\n    if (k < static_cast<int>(below.size())) {\n        return kth(below, k);\n    }\n    if (k >= lessOrEqual) {\n        return kth(above, k - lessOrEqual);\n    }\n    return pivot;\n}\n\nint main() {\n    std::vector<int> items = {4, 9, 2, 7, 4, 1, 8};\n    for (int k = 0; k < static_cast<int>(items.size()); k++) std::cout << (k > 0 ? \" \" : \"\") << kth(items, k);\n    std::cout << std::endl;\n    return 0;\n}\n")]
    [InlineData("kth.dart", "int kth(List<int> items, int k) {\n  final pivot = items[0];\n  final below = items.where((x) => x < pivot).toList();\n  final above = items.where((x) => x > pivot).toList();\n  final lessOrEqual = items.length - above.length;\n  if (k < below.length) {\n    return kth(below, k);\n  }\n  if (k >= lessOrEqual) {\n    return kth(above, k - lessOrEqual);\n  }\n  return pivot;\n}\n\nvoid main() {\n  final items = [4, 9, 2, 7, 4, 1, 8];\n  print(List.generate(items.length, (k) => kth(items, k)).join(' '));\n}\n")]
    [InlineData("kth.f90", "module select_module\n  implicit none\ncontains\n  recursive function kth(items, k) result(found)\n    integer, intent(in) :: items(:), k\n    integer :: found, pivot, less_or_equal\n    pivot = items(1)\n    less_or_equal = size(items) - count(items > pivot)\n    if (k <= count(items < pivot)) then\n      found = kth(pack(items, items < pivot), k)\n    else if (k > less_or_equal) then\n      found = kth(pack(items, items > pivot), k - less_or_equal)\n    else\n      found = pivot\n    end if\n  end function kth\nend module select_module\n\nprogram kth_program\n  use select_module\n  implicit none\n  integer :: items(7) = [4, 9, 2, 7, 4, 1, 8], k, found(7)\n  do k = 1, 7\n    found(k) = kth(items, k)\n  end do\n  print '(*(I0, :, 1X))', found\nend program kth_program\n")]
    [InlineData("kth.go", "package main\n\nimport (\n\t\"fmt\"\n\t\"strings\"\n)\n\nfunc kth(items []int, k int) int {\n\tpivot := items[0]\n\tvar below, above []int\n\tfor _, x := range items {\n\t\tif x < pivot {\n\t\t\tbelow = append(below, x)\n\t\t} else if x > pivot {\n\t\t\tabove = append(above, x)\n\t\t}\n\t}\n\tlessOrEqual := len(items) - len(above)\n\tif k < len(below) {\n\t\treturn kth(below, k)\n\t}\n\tif k >= lessOrEqual {\n\t\treturn kth(above, k - lessOrEqual)\n\t}\n\treturn pivot\n}\n\nfunc main() {\n\titems := []int{4, 9, 2, 7, 4, 1, 8}\n\tvar words []string\n\tfor k := range items {\n\t\twords = append(words, fmt.Sprint(kth(items, k)))\n\t}\n\tfmt.Println(strings.Join(words, \" \"))\n}\n")]
    [InlineData("Kth.java", "import java.util.ArrayList;\nimport java.util.List;\n\npublic class Kth {\n    static int kth(List<Integer> arr, int k) {\n        int pivot = arr.get(0);\n        List<Integer> below = new ArrayList<>();\n        List<Integer> above = new ArrayList<>();\n        for (int x : arr) {\n            if (x < pivot) {\n                below.add(x);\n            } else if (x > pivot) {\n                above.add(x);\n            }\n        }\n        int numLess = below.size();\n        int numLessOrEqual = arr.size() - above.size();\n        if (k < numLess) {\n            return kth(below, k);\n        } else if (k >= numLessOrEqual) {\n            return kth(above, k - numLessOrEqual);\n        } else {\n            return pivot;\n        }\n    }\n\n    public static void main(String[] args) {\n        List<Integer> items = List.of(4, 9, 2, 7, 4, 1, 8);\n        StringBuilder line = new StringBuilder();\n        for (int k = 0; k < items.size(); k++) line.append(k > 0 ? \" \" : \"\").append(kth(items, k));\n        System.out.println(line);\n    }\n}\n")]
