    [InlineData("kth.lua", "local function kth(items, k)\n  local pivot = items[1]\n  local below, above = {}, {}\n  for _, x in ipairs(items) do\n    if x < pivot then\n      below[#below + 1] = x\n    elseif x > pivot then\n      above[#above + 1] = x\n    end\n  end\n  local less_or_equal = #items - #above\n  if k <= #below then\n    return kth(below, k)\n  elseif k > less_or_equal then\n    return kth(above, k - less_or_equal)\n  end\n  return pivot\nend\n\nlocal items = { 4, 9, 2, 7, 4, 1, 8 }\nlocal words = {}\nfor k = 1, #items do\n  words[k] = kth(items, k)\nend\nprint(table.concat(words, \" \"))\n")]
    [InlineData("kth.php", "<?php\nfunction kth(array $items, int $k): int\n{\n    $pivot = $items[0];\n    $below = array_values(array_filter($items, fn($x) => $x < $pivot));\n    $above = array_values(array_filter($items, fn($x) => $x > $pivot));\n    $lessOrEqual = count($items) - count($above);\n    if ($k < count($below)) {\n        return kth($below, $k);\n    }\n    if ($k >= $lessOrEqual) {\n        return kth($above, $k - $lessOrEqual);\n    }\n    return $pivot;\n}\n\n$items = [4, 9, 2, 7, 4, 1, 8];\necho implode(\" \", array_map(fn($k) => kth($items, $k), range(0, count($items) - 1))), \"\\n\";\n")]
    [InlineData("kth.pl", "use strict;\nuse warnings;\n\nsub kth {\n    my ($items, $k) = @_;\n    my $pivot = $items->[0];\n    my @below = grep { $_ < $pivot } @$items;\n    my @above = grep { $_ > $pivot } @$items;\n    my $less_or_equal = @$items - @above;\n    if ($k < @below) {\n        return kth(\\@below, $k);\n    }\n    if ($k >= $less_or_equal) {\n        return kth(\\@above, $k - $less_or_equal);\n    }\n    return $pivot;\n}\n\nmy @items = (4, 9, 2, 7, 4, 1, 8);\nprint join(\" \", map { kth(\\@items, $_) } 0 .. $#items), \"\\n\";\n")]
    [InlineData("kth.ps1", "function Get-Kth($items, [int]$k) {\n    $pivot = $items[0]\n    $below = @($items | Where-Object { $_ -lt $pivot })\n    $above = @($items | Where-Object { $_ -gt $pivot })\n    $lessOrEqual = $items.Count - $above.Count\n    if ($k -lt $below.Count) {\n        return Get-Kth $below $k\n    }\n    if ($k -ge $lessOrEqual) {\n        return Get-Kth $above ($k - $lessOrEqual)\n    }\n    return $pivot\n}\n\n$items = @(4, 9, 2, 7, 4, 1, 8)\n(0..($items.Count - 1) | ForEach-Object { Get-Kth $items $_ }) -join \" \"\n")]
    [InlineData("kth.py", "def kth(arr, k):\n    pivot = arr[0]\n    below = [x for x in arr if x < pivot]\n    above = [x for x in arr if x > pivot]\n\n    num_less = len(below)\n    num_lessoreq = len(arr) - len(above)\n\n    if k < num_less:\n        return kth(below, k)\n    elif k >= num_lessoreq:\n        return kth(above, k - num_lessoreq)\n    else:\n        return pivot\n\n\nitems = [4, 9, 2, 7, 4, 1, 8]\nprint(*(kth(items, k) for k in range(len(items))))\n")]
    [InlineData("kth.rb", "def kth(items, k)\n  pivot = items[0]\n  below = items.select { |x| x < pivot }\n  above = items.select { |x| x > pivot }\n  less_or_equal = items.length - above.length\n  if k < below.length\n    kth(below, k)\n  elsif k >= less_or_equal\n    kth(above, k - less_or_equal)\n  else\n    pivot\n  end\nend\n\nitems = [4, 9, 2, 7, 4, 1, 8]\nputs (0...items.length).map { |k| kth(items, k) }.join(\" \")\n")]
    [InlineData("kth.rs", "fn kth(items: &[i32], k: usize) -> i32 {\n    let pivot = items[0];\n    let below: Vec<i32> = items.iter().copied().filter(|&x| x < pivot).collect();\n    let above: Vec<i32> = items.iter().copied().filter(|&x| x > pivot).collect();\n    let less_or_equal = items.len() - above.len();\n    if k < below.len() {\n        return kth(&below, k);\n    }\n    if k >= less_or_equal {\n        return kth(&above, k - less_or_equal);\n    }\n    pivot\n}\n\nfn main() {\n    let items = [4, 9, 2, 7, 4, 1, 8];\n    let words: Vec<String> = (0..items.len()).map(|k| kth(&items, k).to_string()).collect();\n    println!(\"{}\", words.join(\" \"));\n}\n")]
    [InlineData("Kth.scala", "object Kth {\n  def kth(items: List[Int], k: Int): Int = {\n    val pivot = items.head\n    val below = items.filter(_ < pivot)\n    val above = items.filter(_ > pivot)\n    val lessOrEqual = items.length - above.length\n    if (k < below.length) {\n      kth(below, k)\n    } else if (k >= lessOrEqual) {\n      kth(above, k - lessOrEqual)\n    } else {\n      pivot\n    }\n  }\n\n  def main(args: Array[String]): Unit = {\n    val items = List(4, 9, 2, 7, 4, 1, 8)\n    println(items.indices.map(kth(items, _)).mkString(\" \"))\n  }\n}\n")]
    [InlineData("kth.ts", "function kth(items: number[], k: number): number {\n  const pivot = items[0];\n  const below = items.filter((x) => x < pivot);\n  const above = items.filter((x) => x > pivot);\n  const lessOrEqual = items.length - above.length;\n  if (k < below.length) {\n    return kth(below, k);\n  }\n  if (k >= lessOrEqual) {\n    return kth(above, k - lessOrEqual);\n  }\n  return pivot;\n}\n\nconst items: number[] = [4, 9, 2, 7, 4, 1, 8];\nconsole.log(items.map((_, k) => kth(items, k)).join(\" \"));\n")]
    [InlineData("Program.cs", "using System;\nusing System.Collections.Generic;\nusing System.Linq;\n\npublic static class Program\n{\n    static int Kth(List<int> items, int k)\n    {\n        var pivot = items[0];\n        var below = items.Where(x => x < pivot).ToList();\n        var above = items.Where(x => x > pivot).ToList();\n        var lessOrEqual = items.Count - above.Count;\n        if (k < below.Count)\n        {\n            return Kth(below, k);\n        }\n\n        if (k >= lessOrEqual)\n        {\n            return Kth(above, k - lessOrEqual);\n        }\n\n        return pivot;\n    }\n\n    public static void Main()\n    {\n        var items = new List<int> { 4, 9, 2, 7, 4, 1, 8 };\n        Console.WriteLine(string.Join(\" \", Enumerable.Range(0, items.Count).Select(k => Kth(items, k))));\n    }\n}\n")]
    [InlineData("inplace.py", "# Quickselect in place: k is a place in the whole array, and each call looks at a part of that same array: prints 1 2 4 4 7 8 9.\ndef select(items, low, high, k):\n    pivot = items[high]\n    store = low\n    for i in range(low, high):\n        if items[i] < pivot:\n            items[i], items[store] = items[store], items[i]\n            store += 1\n    items[store], items[high] = items[high], items[store]\n    if k < store:\n        return select(items, low, store - 1, k)\n    if k > store:\n        return select(items, store + 1, high, k)\n    return items[store]\n\n\nvalues = [4, 9, 2, 7, 4, 1, 8]\nprint(*(select(values[:], 0, len(values) - 1, k) for k in range(len(values))))\n")]
    [InlineData("largest.js", "// The k-th largest: the part above the pivot comes first counting from the top, so k is kept going into it: prints 9 8 7 4 4 2 1.\nfunction kthLargest(items, k) {\n  const pivot = items[0];\n  const above = items.filter((x) => x > pivot);\n  const below = items.filter((x) => x < pivot);\n  const upToPivot = items.length - below.length;\n  if (k < above.length) return kthLargest(above, k);\n  if (k >= upToPivot) return kthLargest(below, k - upToPivot);\n  return pivot;\n}\n\nconst items = [4, 9, 2, 7, 4, 1, 8];\nconsole.log(items.map((_, k) => kthLargest(items, k)).join(\" \"));\n")]
    [InlineData("Search.java", "// A binary search over a sorted array, the target kept as it is in each half: prints 3.\npublic class Search {\n    static int search(int[] items, int target, int start, int end) {\n        if (start == end) return -1;\n        int mid = start + (end - start) / 2;\n        if (target < items[mid]) {\n            return search(items, target, start, mid);\n        } else if (target > items[mid]) {\n            return search(items, target, mid + 1, end);\n        }\n        return mid;\n    }\n\n    public static void main(String[] args) {\n        System.out.println(search(new int[] {1, 2, 4, 7, 8, 9}, 7, 0, 6));\n    }\n}\n")]
    public void APlaceTakenAwayOrKeptRightlyIsLeftAlone(string fileName, string code)
    {
        // Each check of the file's own language, as FixFinder runs them.
        var file = Program(fileName, code);
        var extension = Path.GetExtension(fileName).ToLowerInvariant();
        Assert.Empty(LogicPatterns.All.Where(pattern => pattern.Id.EndsWith("place-not-taken-away", StringComparison.Ordinal) && pattern.Extensions.Contains(extension))
            .SelectMany(pattern => pattern.Find(file)));
    }
}
